import {clone,progress,status,missing,createDossier,reminder} from './core.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='dossier-clair-v1';
const date=d=>d?new Date(d+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'short'}):'Sans échéance';
const today=()=>new Date().toLocaleDateString('en-CA');
const field=(label,type='text')=>({label,type});
function initial(){const templates=[{id:'web',name:'Création de site web',description:'Les textes, visuels et informations utiles pour lancer un site.',version:1,fields:[field('Présentation de votre entreprise'),field('Logo et identité visuelle','file'),field('Textes des pages'),field('Photographies','file')]},{id:'brand',name:'Identité de marque',description:'Un brief clair pour donner vie à une nouvelle identité.',version:1,fields:[field('Votre activité et vos valeurs'),field('Vos clients idéaux'),field('Vos inspirations','file')]},{id:'campaign',name:'Campagne de communication',description:'Centralisez le brief, les messages et les éléments de campagne.',version:1,fields:[field('Objectifs de la campagne'),field('Message principal'),field('Visuels de la campagne','file')]}];const ds=[createDossier(templates[0],'Refonte du site internet','Maison Alba','2026-11-12'),createDossier(templates[1],'Une nouvelle identité','Studio Mistral','2026-11-09'),createDossier(templates[2],'Campagne de fin d’année','Les Jardins','2026-11-20')];ds[0].items[0].answer='Maison Alba, un atelier de céramique artisanale à Bordeaux.';ds[0].items[0].status='accepted';ds[0].items[2].answer='Accueil : des objets uniques, faits pour durer.';ds[0].items[2].status='submitted';ds[1].items[0].answer='Un studio indépendant de design engagé.';ds[1].items[0].status='submitted';return {org:'Atelier Studio',templates,dossiers:ds};}
let state;try{state=JSON.parse(localStorage.getItem(key))||initial()}catch{state=initial()}
let page='dashboard',selected=null,client=false,search='',filter='all';
function save(){try{localStorage.setItem(key,JSON.stringify(state));return true}catch{toast('Stockage plein : exportez vos données et réduisez les fichiers.');return false}}
function log(d,text){d.history.unshift({date:new Date().toISOString(),text})}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
function badge(d){const s=status(d);return `<span class="badge ${s==='À valider'?'wait':d.paused?'pause':''}">${s}</span>`}
function heading(title,subtitle,action=''){return `<div class="heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`}
const newButton='<button class="btn primary" data-action="new">＋ Nouveau dossier</button>';
function rows(){const ds=state.dossiers.filter(d=>(d.name+' '+d.client).toLowerCase().includes(search.toLowerCase())&&(filter==='all'||status(d)===filter));return ds.length?ds.map(d=>`<tr><td class="doc-name"><button data-open="${d.id}">${esc(d.name)}</button><small>${esc(d.client)}</small></td><td>${badge(d)}</td><td>${progress(d)} %<div class="bar"><i style="width:${progress(d)}%"></i></div></td><td class="mobile-hide">${date(d.due)}</td><td><button class="link" data-open="${d.id}" aria-label="Ouvrir ${esc(d.name)}">↗</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">Aucun dossier trouvé.</td></tr>'}
function table(){return `<div class="panel"><div class="filters"><input type="search" id="search" placeholder="Rechercher un dossier ou un client…" value="${esc(search)}" aria-label="Rechercher"><select id="filter" aria-label="Filtrer par statut">${['all','En collecte','À valider','En pause','Terminé'].map(s=>`<option value="${s}" ${s===filter?'selected':''}>${s==='all'?'Tous les statuts':s}</option>`).join('')}</select></div><table><thead><tr><th>Dossier / Client</th><th>Statut</th><th>Progression</th><th class="mobile-hide">Échéance</th><th></th></tr></thead><tbody id="rows">${rows()}</tbody></table></div>`}
function dashboard(){const pending=state.dossiers.reduce((n,d)=>n+d.items.filter(i=>i.status==='submitted').length,0);return heading('Tout est plus clair.','Vos dossiers, vos clients, votre prochain pas.',newButton)+`<div class="hero"><div><span class="eyebrow">Votre espace de travail</span><h2>Les bons éléments.<br>Au bon endroit.</h2><p>Centralisez les demandes et accompagnez vos clients jusqu’au dossier complet.</p><button class="btn" data-nav="templates">Explorer les modèles <span>↗</span></button></div><div class="hero-art" aria-hidden="true"><div class="paper"><b>Votre projet ✓</b><div></div><div></div><div></div><b>✓ &nbsp; ✓ &nbsp; ○</b></div></div></div><div class="stats">${[[state.dossiers.filter(d=>!d.paused&&status(d)!=='Terminé').length,'Dossiers actifs','Vos projets en cours'],[pending,'Éléments à valider','À vous de jouer'],[state.dossiers.filter(d=>missing(d).length&&!d.paused).length,'Dossiers incomplets','Des éléments à recevoir'],[state.dossiers.filter(d=>status(d)==='Terminé').length,'Dossiers terminés','Tout est prêt']].map(([n,l,t])=>`<div class="stat"><label>${l}</label><strong>${n.toString().padStart(2,'0')}</strong><small>${t}</small></div>`).join('')}</div><div class="section-head"><h2>Vos dossiers</h2><button class="link" data-nav="dossiers">Tous les dossiers →</button></div>${table()}<div class="lower"><div class="card"><span class="eyebrow" style="color:#7a8b6c">Un démarrage simple</span><h3>Votre méthode, prête à être réutilisée.</h3><p>Adaptez les questions d’un modèle. Chaque nouveau dossier reprend votre configuration, sans modifier les projets déjà ouverts.</p><button class="btn" data-nav="templates">Personnaliser mes modèles →</button></div><div class="card"><h3>Dernières activités</h3>${state.dossiers.flatMap(d=>d.history.slice(0,2).map(h=>({...h,name:d.client}))).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3).map(h=>`<div class="activity"><span class="dot">✓</span><div>${esc(h.text)}<small>${esc(h.name)}</small></div></div>`).join('')}</div></div>`}
function templates(){return heading('Vos modèles, votre méthode.','Un cadre réutilisable. Des dossiers personnalisés sans code.','<button class="btn primary" data-action="template-new">＋ Créer un modèle</button>')+`<div class="template-grid">${state.templates.map(t=>`<div class="card"><div class="template-icon">▤</div><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><small>${t.fields.length} éléments · version ${t.version}</small><button class="btn primary" data-template-use="${t.id}">Utiliser ce modèle</button><button class="link" data-template-edit="${t.id}">Modifier les questions</button></div>`).join('')}</div>`}
function detail(){const d=state.dossiers.find(d=>d.id===selected);if(!d){page='dossiers';return table()}return heading(esc(d.name),`${esc(d.client)} · Échéance ${date(d.due)} · Modèle v${d.version}`,`<button class="btn" data-action="toggle-client">${client?'← Vue agence':'Aperçu client →'}</button>`)+`<div class="actions" style="margin-bottom:20px"><button class="link" data-nav="dossiers">← Dossiers</button>${badge(d)}<button class="btn" data-action="export">↓ Exporter JSON + fichiers</button>${!client?`<button class="btn" data-action="pause">${d.paused?'Reprendre':'Mettre en pause'}</button><button class="btn" data-action="remind" ${d.paused||!missing(d).length?'disabled':''}>Simuler une relance</button>`:''}</div>${client?'<div class="client-banner"><b>Aperçu du parcours client</b><small>Simulation dans votre navigateur, sans accès externe. Réponses et fichiers de test uniquement.</small></div>':''}<div class="detail-grid"><div class="panel">${d.items.map((i,idx)=>`<div class="item"><div class="item-head"><h3>${idx+1}. ${esc(i.label)}</h3><span class="badge ${i.status==='submitted'||i.status==='revision'?'wait':''}">${{missing:'À fournir',submitted:'À valider',accepted:'Validé',revision:'À corriger'}[i.status]}</span></div>${i.comment?`<div class="comment">${esc(i.comment)}</div>`:''}${client?`${i.type==='text'?`<textarea aria-label="${esc(i.label)}" data-answer="${i.id}" placeholder="Votre réponse…" ${d.paused?'disabled':''}>${esc(i.answer)}</textarea>`:`<p>Fichier de test · 1 Mo maximum. PDF, PNG, JPG ou TXT.</p><input type="file" accept=".pdf,.png,.jpg,.jpeg,.txt" data-file="${i.id}" aria-label="${esc(i.label)}" ${d.paused?'disabled':''}>${i.file?`<p>📎 ${esc(i.file.name)}</p>`:''}`}<div class="actions"><button class="btn primary" data-submit="${i.id}" ${d.paused?'disabled':''}>Transmettre cet élément</button></div>`:`${i.answer?`<div class="answer">${esc(i.answer)}</div>`:''}${i.file?`<button class="btn" data-download="${i.id}">↓ ${esc(i.file.name)}</button>`:''}${i.status==='missing'?'<p>Votre client n’a pas encore transmis cet élément.</p>':''}<div class="actions"><button class="btn primary" data-accept="${i.id}" ${i.status!=='submitted'||d.paused?'disabled':''}>✓ Valider</button><button class="btn" data-revise="${i.id}" ${!['submitted','accepted'].includes(i.status)||d.paused?'disabled':''}>Demander une correction</button></div>`}</div>`).join('')}</div><div class="card"><h3>Avancement du dossier</h3><strong style="font-size:36px;display:block;margin-top:20px">${progress(d)} %</strong><div class="bar" style="width:100%"><i style="width:${progress(d)}%"></i></div><p>${d.items.filter(i=>i.status==='accepted').length} élément(s) validé(s) sur ${d.items.length}</p><h3 style="margin-top:26px">Historique local</h3>${d.history.slice(0,8).map(h=>`<div class="activity"><div>${esc(h.text)}<small>${new Date(h.date).toLocaleString('fr-FR')}</small></div></div>`).join('')}</div></div>`}
function settings(){return heading('Un espace à votre image.','Personnalisez votre espace de démonstration.')+`<div class="card" style="max-width:620px"><form class="form" id="settings"><label>Nom de votre organisation<input name="org" required maxlength="60" value="${esc(state.org)}"></label><button class="btn primary">Enregistrer</button></form><h3 style="margin-top:30px">Vos données de test</h3><p>Les données restent dans ce navigateur. L’export JSON contient les réponses, fichiers encodés, modèles et historique. Aucun serveur de stockage ni email n’est connecté.</p><button class="btn" data-action="export-all">Télécharger une sauvegarde</button><h3 style="margin-top:30px">Avant un pilote réel</h3><p>Comptes et permissions côté serveur, stockage privé, invitations révocables et relances email devront être raccordés et testés.</p></div>`}
function render(){document.documentElement.style.setProperty('--green','#154c43');$('#org').textContent=state.org;$('#count').textContent=state.dossiers.length;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.nav===(page==='detail'?'dossiers':page)));$('#breadcrumb').textContent='Votre espace / '+({dashboard:'Vue d’ensemble',dossiers:'Mes dossiers',templates:'Modèles',settings:'Personnalisation',detail:'Détail du dossier'}[page]);$('#app').innerHTML=page==='dashboard'?dashboard():page==='dossiers'?heading('Tous vos dossiers.','Gardez une vue claire sur chaque projet.',newButton)+table():page==='templates'?templates():page==='detail'?detail():settings();}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
function newDossier(templateId){modal(`<form class="form" id="new"><h2>Nouveau dossier</h2><label>Nom du projet<input name="name" required maxlength="100" placeholder="Ex. Création du site internet"></label><label>Nom du client<input name="client" required maxlength="80" placeholder="Ex. Maison Alba"></label><label>Modèle<select name="template">${state.templates.map(t=>`<option value="${t.id}" ${t.id===templateId?'selected':''}>${esc(t.name)} · v${t.version}</option>`).join('')}</select></label><label>Échéance<input name="due" type="date" required></label><button class="btn primary">Créer le dossier</button><small>Création locale uniquement. Aucune invitation n’est envoyée.</small></form>`)}
function editTemplate(id){const t=state.templates.find(t=>t.id===id);modal(`<form class="form" id="template" data-id="${id||''}"><h2>${t?'Modifier':'Créer'} un modèle</h2><label>Nom<input name="name" required maxlength="80" value="${esc(t?.name||'')}"></label><label>Description<input name="description" maxlength="200" value="${esc(t?.description||'')}"></label><label>Questions, une par ligne<textarea name="fields" required placeholder="Présentation de l’entreprise&#10;Logo | fichier">${esc(t?.fields.map(f=>f.label+(f.type==='file'?' | fichier':'')).join('\n')||'')}</textarea></label><small>Ajoutez « | fichier » après une question pour demander un document. L’ordre des lignes définit l’ordre des questions. Les dossiers existants gardent leur version.</small><button class="btn primary">Enregistrer le modèle</button></form>`)}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function persist(){save();render()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset;const d=state.dossiers.find(d=>d.id===selected);if(a.nav){page=a.nav;client=false;render();return}if(a.open){selected=a.open;page='detail';client=false;render();return}if(a.templateUse){newDossier(a.templateUse);return}if(a.templateEdit){editTemplate(a.templateEdit);return}if(b.classList.contains('close')){$('#modal').close();return}if(a.action==='new')newDossier();if(a.action==='template-new')editTemplate();if(a.action==='toggle-client'){client=!client;render()}if(a.action==='export')download('dossier-clair-'+d.id+'.json',JSON.stringify(d,null,2));if(a.action==='export-all')download('dossier-clair-sauvegarde.json',JSON.stringify(state,null,2));if(a.action==='pause'){d.paused=!d.paused;log(d,d.paused?'Dossier mis en pause':'Collecte reprise');persist()}if(a.action==='remind'){const ok=reminder(d,today());persist();toast(ok?'Relance simulée. Aucun email envoyé.':'Déjà simulée aujourd’hui, ou aucun élément à relancer.')}if(a.accept){const i=d.items.find(i=>i.id===a.accept);i.status='accepted';i.comment='';log(d,'Élément validé : '+i.label);persist()}if(a.revise){modal(`<form class="form" id="revision" data-id="${a.revise}"><h2>Demander une correction</h2><label>Ce que le client doit modifier<textarea name="comment" required maxlength="1000"></textarea></label><button class="btn primary">Enregistrer la demande</button></form>`)}if(a.submit){const i=d.items.find(i=>i.id===a.submit);if(i.type==='text'?!i.answer.trim():!i.file){toast('Ajoutez une réponse ou un fichier avant de transmettre.');return}i.status='submitted';log(d,'Élément transmis : '+i.label);persist();toast('Élément transmis dans la démonstration.')}if(a.download){const f=d.items.find(i=>i.id===a.download).file;const bin=atob(f.data.split(',')[1]);download(f.name,Uint8Array.from(bin,c=>c.charCodeAt(0)),'application/octet-stream')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#rows').innerHTML=rows()}if(e.target.dataset.answer){const d=state.dossiers.find(d=>d.id===selected);const i=d.items.find(i=>i.id===e.target.dataset.answer);i.answer=e.target.value;if(i.status==='accepted'||i.status==='submitted')i.status='missing';save()}});
document.addEventListener('change',async e=>{if(e.target.id==='filter'){filter=e.target.value;$('#rows').innerHTML=rows()}if(e.target.dataset.file){const f=e.target.files[0];if(!f)return;if(f.size>1024*1024||! /\.(pdf|png|jpe?g|txt)$/i.test(f.name)){toast('Choisissez un PDF, PNG, JPG ou TXT de moins de 1 Mo.');e.target.value='';return}const d=state.dossiers.find(d=>d.id===selected);const i=d.items.find(i=>i.id===e.target.dataset.file);const before=clone(i);const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(f)}).catch(()=>null);if(!data){toast('Lecture du fichier impossible.');return}i.file={name:f.name,type:f.type,data};i.status='missing';if(!save())Object.assign(i,before);render()}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,v=new FormData(f);if(f.id==='new'){const d=createDossier(state.templates.find(t=>t.id===v.get('template')),v.get('name').trim(),v.get('client').trim(),v.get('due'));if(!d.name||!d.client)return;state.dossiers.unshift(d);selected=d.id;page='detail';client=false}if(f.id==='template'){const fields=v.get('fields').split('\n').map(l=>l.trim()).filter(Boolean).map(l=>field(l.replace(/\s*\|\s*fichier\s*$/i,''),/\|\s*fichier\s*$/i.test(l)?'file':'text'));if(!fields.length||fields.some(f=>!f.label.trim())){toast('Ajoutez au moins une question avec un libellé.');return}const old=state.templates.find(t=>t.id===f.dataset.id);const t={id:old?.id||crypto.randomUUID(),name:v.get('name').trim(),description:v.get('description').trim(),fields,version:(old?.version||0)+1};if(old)state.templates[state.templates.indexOf(old)]=t;else state.templates.push(t)}if(f.id==='revision'){const d=state.dossiers.find(d=>d.id===selected),i=d.items.find(i=>i.id===f.dataset.id);i.comment=v.get('comment').trim();if(!i.comment)return;i.status='revision';log(d,'Correction demandée : '+i.label)}if(f.id==='settings'){if(!v.get('org').trim())return;state.org=v.get('org').trim();toast('Personnalisation enregistrée.')}$('#modal').close();persist()});
render();
